begin;create extension if not exists pgtap with schema extensions;select plan(12);select has_table('public','question_qa_versions','Question QA is versioned');select has_table('public','generated_candidate_questions','Candidate questions remain private');select has_column('public','generated_candidate_questions','declared_competency_id','Declared competency is linked');select has_column('public','generated_candidate_questions','declared_demand','Declared demand is explicit');select has_column('public','generated_candidate_questions','tense_focus','Tense purpose is explicit');select has_table('public','question_qa_results','Question QA evidence persists');select has_column('public','question_qa_results','passage_qa_result_id','Questions bind to final passage QA');select has_column('public','question_qa_results','independent_answer','Independent answer is retained');select has_column('public','question_qa_results','evidence_spans','Passage support is retained');select has_column('public','question_qa_results','defensible_answers','Ambiguity is retained');select has_column('public','question_qa_results','distractor_analysis','Distractors are analyzed');select col_is_unique('public','question_qa_results',array['question_id','qa_version_id'],'One result per question and QA version');select * from finish();rollback;
